#pragma once
#include <map>
#include <memory>
#include <set>
#include <string>
#include <iostream>
namespace ast {
class Node;
using Ptr = std::unique_ptr<Node>;
using Env = std::map<std::string, double>;

// Forward declarations for visitor classes
class EvalVisitor;
class PrintVisitor;
class VarsVisitor;
class CloneVisitor;
class FoldVisitor;
class DiffVisitor;

// Base Node class
class Node {
public:
    virtual ~Node() = default;
    virtual void accept(EvalVisitor& visitor) const = 0;
    virtual void accept(PrintVisitor& visitor) const = 0;
    virtual void accept(VarsVisitor& visitor) const = 0;
    virtual void accept(CloneVisitor& visitor) const = 0;
    virtual void accept(FoldVisitor& visitor) const = 0;
    virtual void accept(DiffVisitor& visitor) const = 0;
};

// Concrete Node types
class NumNode : public Node {
public:
    double value;
    NumNode(double v) : value(v) {}

    void accept(EvalVisitor& visitor) const override;
    void accept(PrintVisitor& visitor) const override;
    void accept(VarsVisitor& visitor) const override;
    void accept(CloneVisitor& visitor) const override;
    void accept(FoldVisitor& visitor) const override;
    void accept(DiffVisitor& visitor) const override;
};

class VarNode : public Node {
public:
    std::string name;
    VarNode(std::string n) : name(std::move(n)) {}

    void accept(EvalVisitor& visitor) const override;
    void accept(PrintVisitor& visitor) const override;
    void accept(VarsVisitor& visitor) const override;
    void accept(CloneVisitor& visitor) const override;
    void accept(FoldVisitor& visitor) const override;
    void accept(DiffVisitor& visitor) const override;
};

class AddNode : public Node {
public:
    Ptr left, right;
    AddNode(Ptr l, Ptr r) : left(std::move(l)), right(std::move(r)) {}

    void accept(EvalVisitor& visitor) const override;
    void accept(PrintVisitor& visitor) const override;
    void accept(VarsVisitor& visitor) const override;
    void accept(CloneVisitor& visitor) const override;
    void accept(FoldVisitor& visitor) const override;
    void accept(DiffVisitor& visitor) const override;
};

class SubNode : public Node {
public:
    Ptr left, right;
    SubNode(Ptr l, Ptr r) : left(std::move(l)), right(std::move(r)) {}

    void accept(EvalVisitor& visitor) const override;
    void accept(PrintVisitor& visitor) const override;
    void accept(VarsVisitor& visitor) const override;
    void accept(CloneVisitor& visitor) const override;
    void accept(FoldVisitor& visitor) const override;
    void accept(DiffVisitor& visitor) const override;
};

class MulNode : public Node {
public:
    Ptr left, right;
    MulNode(Ptr l, Ptr r) : left(std::move(l)), right(std::move(r)) {}

    void accept(EvalVisitor& visitor) const override;
    void accept(PrintVisitor& visitor) const override;
    void accept(VarsVisitor& visitor) const override;
    void accept(CloneVisitor& visitor) const override;
    void accept(FoldVisitor& visitor) const override;
    void accept(DiffVisitor& visitor) const override;
};

class NegNode : public Node {
public:
    Ptr operand;
    NegNode(Ptr op) : operand(std::move(op)) {}

    void accept(EvalVisitor& visitor) const override;
    void accept(PrintVisitor& visitor) const override;
    void accept(VarsVisitor& visitor) const override;
    void accept(CloneVisitor& visitor) const override;
    void accept(FoldVisitor& visitor) const override;
    void accept(DiffVisitor& visitor) const override;
};

class PowNode : public Node {
public:
    Ptr base;
    double exponent;
    PowNode(Ptr b, double e) : base(std::move(b)), exponent(e) {}

    void accept(EvalVisitor& visitor) const override;
    void accept(PrintVisitor& visitor) const override;
    void accept(VarsVisitor& visitor) const override;
    void accept(CloneVisitor& visitor) const override;
    void accept(FoldVisitor& visitor) const override;
    void accept(DiffVisitor& visitor) const override;
};

class ExpNode : public Node {
public:
    Ptr operand;
    ExpNode(Ptr op) : operand(std::move(op)) {}

    void accept(EvalVisitor& visitor) const override;
    void accept(PrintVisitor& visitor) const override;
    void accept(VarsVisitor& visitor) const override;
    void accept(CloneVisitor& visitor) const override;
    void accept(FoldVisitor& visitor) const override;
    void accept(DiffVisitor& visitor) const override;
};

class LogNode : public Node {
public:
    Ptr operand;
    LogNode(Ptr op) : operand(std::move(op)) {}

    void accept(EvalVisitor& visitor) const override;
    void accept(PrintVisitor& visitor) const override;
    void accept(VarsVisitor& visitor) const override;
    void accept(CloneVisitor& visitor) const override;
    void accept(FoldVisitor& visitor) const override;
    void accept(DiffVisitor& visitor) const override;
};

Ptr num(double v);
Ptr var(std::string name);
Ptr add(Ptr a, Ptr b);
Ptr sub(Ptr a, Ptr b);
Ptr mul(Ptr a, Ptr b);
Ptr neg(Ptr a);
Ptr pow_(Ptr base, double exponent);
Ptr exp_(Ptr a);
Ptr log_(Ptr a);

double eval(const Node& n, const Env& env);   // std::out_of_range on an unknown variable
std::string print(const Node& n);
std::set<std::string> vars(const Node& n);
Ptr clone(const Node& n);
Ptr fold(const Node& n);                      // new tree, input untouched
Ptr diff(const Node& n, const std::string& x);// new tree, input untouched
}  // namespace ast

