#include "ast.hpp"
#include <stdexcept>
#include <sstream>
#include <cmath>
#include <algorithm>
#include <memory>

namespace ast {
// Helper function to check if a node is a number
bool is_num(const Node& node) {
    return dynamic_cast<const NumNode*>(&node) != nullptr;
}

// Helper function to get the value of a number node
double get_num_value(const Node& node) {
    const NumNode* num_node = dynamic_cast<const NumNode*>(&node);
    if (num_node) {
        return num_node->value;
    }
    throw std::runtime_error("Node is not a number");
}

// Helper function to check if a node is a variable
bool is_var(const Node& node) {
    return dynamic_cast<const VarNode*>(&node) != nullptr;
}

// Helper function to get the name of a variable node
std::string get_var_name(const Node& node) {
    const VarNode* var_node = dynamic_cast<const VarNode*>(&node);
    if (var_node) {
        return var_node->name;
    }
    throw std::runtime_error("Node is not a variable");
}

// Visitor implementations
class EvalVisitor {
public:
    const Env& env;
    double result;

    EvalVisitor(const Env& e) : env(e), result(0) {}

    void visit(const NumNode& node) {
        result = node.value;
    }

    void visit(const VarNode& node) {
        auto it = env.find(node.name);
        if (it == env.end()) {
            throw std::out_of_range("Unknown variable: " + node.name);
        }
        result = it->second;
    }

    void visit(const AddNode& node) {
        EvalVisitor left_visitor(env);
        node.left->accept(left_visitor);
        EvalVisitor right_visitor(env);
        node.right->accept(right_visitor);
        result = left_visitor.result + right_visitor.result;
    }

    void visit(const SubNode& node) {
        EvalVisitor left_visitor(env);
        node.left->accept(left_visitor);
        EvalVisitor right_visitor(env);
        node.right->accept(right_visitor);
        result = left_visitor.result - right_visitor.result;
    }

    void visit(const MulNode& node) {
        EvalVisitor left_visitor(env);
        node.left->accept(left_visitor);
        EvalVisitor right_visitor(env);
        node.right->accept(right_visitor);
        result = left_visitor.result * right_visitor.result;
    }

    void visit(const NegNode& node) {
        EvalVisitor operand_visitor(env);
        node.operand->accept(operand_visitor);
        result = -operand_visitor.result;
    }

    void visit(const PowNode& node) {
        EvalVisitor base_visitor(env);
        node.base->accept(base_visitor);
        result = std::pow(base_visitor.result, node.exponent);
    }

    void visit(const ExpNode& node) {
        EvalVisitor operand_visitor(env);
        node.operand->accept(operand_visitor);
        result = std::exp(operand_visitor.result);
    }

    void visit(const LogNode& node) {
        EvalVisitor operand_visitor(env);
        node.operand->accept(operand_visitor);
        result = std::log(operand_visitor.result);
    }
};

class PrintVisitor {
public:
    std::string result;
    int precedence;

    PrintVisitor() : result(""), precedence(0) {}

    void visit(const NumNode& node) {
        std::ostringstream oss;
        oss.precision(17);
        oss << node.value;
        result = oss.str();
    }

    void visit(const VarNode& node) {
        result = node.name;
    }

    void visit(const AddNode& node) {
        PrintVisitor left_visitor;
        node.left->accept(left_visitor);
        PrintVisitor right_visitor;
        node.right->accept(right_visitor);

        bool need_parens_left = (left_visitor.precedence < 1);
        bool need_parens_right = (right_visitor.precedence <= 1);

        if (need_parens_left) {
            result = "(" + left_visitor.result + ") + " + right_visitor.result;
        } else if (need_parens_right) {
            result = left_visitor.result + " + (" + right_visitor.result + ")";
        } else {
            result = left_visitor.result + " + " + right_visitor.result;
        }
        precedence = 1;
    }

    void visit(const SubNode& node) {
        PrintVisitor left_visitor;
        node.left->accept(left_visitor);
        PrintVisitor right_visitor;
        node.right->accept(right_visitor);

        bool need_parens_left = (left_visitor.precedence < 1);
        bool need_parens_right = (right_visitor.precedence <= 1);

        if (need_parens_left) {
            result = "(" + left_visitor.result + ") - " + right_visitor.result;
        } else if (need_parens_right) {
            result = left_visitor.result + " - (" + right_visitor.result + ")";
        } else {
            result = left_visitor.result + " - " + right_visitor.result;
        }
        precedence = 1;
    }

    void visit(const MulNode& node) {
        PrintVisitor left_visitor;
        node.left->accept(left_visitor);
        PrintVisitor right_visitor;
        node.right->accept(right_visitor);

        bool need_parens_left = (left_visitor.precedence < 2);
        bool need_parens_right = (right_visitor.precedence <= 2);

        if (need_parens_left) {
            result = "(" + left_visitor.result + ") * " + right_visitor.result;
        } else if (need_parens_right) {
            result = left_visitor.result + " * (" + right_visitor.result + ")";
        } else {
            result = left_visitor.result + " * " + right_visitor.result;
        }
        precedence = 2;
    }

    void visit(const NegNode& node) {
        PrintVisitor operand_visitor;
        node.operand->accept(operand_visitor);

        // For unary minus, we need parentheses if the operand has lower precedence
        bool need_parens = (operand_visitor.precedence < 3);

        if (need_parens) {
            result = "-(" + operand_visitor.result + ")";
        } else {
            result = "-" + operand_visitor.result;
        }
        precedence = 3;
    }

    void visit(const PowNode& node) {
        PrintVisitor base_visitor;
        node.base->accept(base_visitor);

        // For power, we need parentheses if the base has lower precedence
        bool need_parens = (base_visitor.precedence < 4);

        if (need_parens) {
            result = "(" + base_visitor.result + ")^" + std::to_string(node.exponent);
        } else {
            result = base_visitor.result + "^" + std::to_string(node.exponent);
        }
        precedence = 4;
    }

    void visit(const ExpNode& node) {
        PrintVisitor operand_visitor;
        node.operand->accept(operand_visitor);
        result = "exp(" + operand_visitor.result + ")";
        precedence = 0;
    }

    void visit(const LogNode& node) {
        PrintVisitor operand_visitor;
        node.operand->accept(operand_visitor);
        result = "log(" + operand_visitor.result + ")";
        precedence = 0;
    }
};

class VarsVisitor {
public:
    std::set<std::string> result;

    void visit(const NumNode& node) {
        // Nothing to do for numbers
    }

    void visit(const VarNode& node) {
        result.insert(node.name);
    }

    void visit(const AddNode& node) {
        VarsVisitor left_visitor;
        node.left->accept(left_visitor);
        VarsVisitor right_visitor;
        node.right->accept(right_visitor);
        result.insert(left_visitor.result.begin(), left_visitor.result.end());
        result.insert(right_visitor.result.begin(), right_visitor.result.end());
    }

    void visit(const SubNode& node) {
        VarsVisitor left_visitor;
        node.left->accept(left_visitor);
        VarsVisitor right_visitor;
        node.right->accept(right_visitor);
        result.insert(left_visitor.result.begin(), left_visitor.result.end());
        result.insert(right_visitor.result.begin(), right_visitor.result.end());
    }

    void visit(const MulNode& node) {
        VarsVisitor left_visitor;
        node.left->accept(left_visitor);
        VarsVisitor right_visitor;
        node.right->accept(right_visitor);
        result.insert(left_visitor.result.begin(), left_visitor.result.end());
        result.insert(right_visitor.result.begin(), right_visitor.result.end());
    }

    void visit(const NegNode& node) {
        VarsVisitor operand_visitor;
        node.operand->accept(operand_visitor);
        result.insert(operand_visitor.result.begin(), operand_visitor.result.end());
    }

    void visit(const PowNode& node) {
        VarsVisitor base_visitor;
        node.base->accept(base_visitor);
        result.insert(base_visitor.result.begin(), base_visitor.result.end());
    }

    void visit(const ExpNode& node) {
        VarsVisitor operand_visitor;
        node.operand->accept(operand_visitor);
        result.insert(operand_visitor.result.begin(), operand_visitor.result.end());
    }

    void visit(const LogNode& node) {
        VarsVisitor operand_visitor;
        node.operand->accept(operand_visitor);
        result.insert(operand_visitor.result.begin(), operand_visitor.result.end());
    }
};

class CloneVisitor {
public:
    Ptr result;

    void visit(const NumNode& node) {
        result = std::make_unique<NumNode>(node.value);
    }

    void visit(const VarNode& node) {
        result = std::make_unique<VarNode>(node.name);
    }

    void visit(const AddNode& node) {
        CloneVisitor left_visitor;
        node.left->accept(left_visitor);
        CloneVisitor right_visitor;
        node.right->accept(right_visitor);
        result = std::make_unique<AddNode>(std::move(left_visitor.result), std::move(right_visitor.result));
    }

    void visit(const SubNode& node) {
        CloneVisitor left_visitor;
        node.left->accept(left_visitor);
        CloneVisitor right_visitor;
        node.right->accept(right_visitor);
        result = std::make_unique<SubNode>(std::move(left_visitor.result), std::move(right_visitor.result));
    }

    void visit(const MulNode& node) {
        CloneVisitor left_visitor;
        node.left->accept(left_visitor);
        CloneVisitor right_visitor;
        node.right->accept(right_visitor);
        result = std::make_unique<MulNode>(std::move(left_visitor.result), std::move(right_visitor.result));
    }

    void visit(const NegNode& node) {
        CloneVisitor operand_visitor;
        node.operand->accept(operand_visitor);
        result = std::make_unique<NegNode>(std::move(operand_visitor.result));
    }

    void visit(const PowNode& node) {
        CloneVisitor base_visitor;
        node.base->accept(base_visitor);
        result = std::make_unique<PowNode>(std::move(base_visitor.result), node.exponent);
    }

    void visit(const ExpNode& node) {
        CloneVisitor operand_visitor;
        node.operand->accept(operand_visitor);
        result = std::make_unique<ExpNode>(std::move(operand_visitor.result));
    }

    void visit(const LogNode& node) {
        CloneVisitor operand_visitor;
        node.operand->accept(operand_visitor);
        result = std::make_unique<LogNode>(std::move(operand_visitor.result));
    }
};

class FoldVisitor {
public:
    Ptr result;

    void visit(const NumNode& node) {
        result = std::make_unique<NumNode>(node.value);
    }

    void visit(const VarNode& node) {
        result = std::make_unique<VarNode>(node.name);
    }

    void visit(const AddNode& node) {
        FoldVisitor left_visitor;
        node.left->accept(left_visitor);
        FoldVisitor right_visitor;
        node.right->accept(right_visitor);

        // Try to fold constants
        if (is_num(*left_visitor.result) && is_num(*right_visitor.result)) {
            double left_val = get_num_value(*left_visitor.result);
            double right_val = get_num_value(*right_visitor.result);
            result = std::make_unique<NumNode>(left_val + right_val);
        } else {
            result = std::make_unique<AddNode>(std::move(left_visitor.result), std::move(right_visitor.result));
        }
    }

    void visit(const SubNode& node) {
        FoldVisitor left_visitor;
        node.left->accept(left_visitor);
        FoldVisitor right_visitor;
        node.right->accept(right_visitor);

        // Try to fold constants
        if (is_num(*left_visitor.result) && is_num(*right_visitor.result)) {
            double left_val = get_num_value(*left_visitor.result);
            double right_val = get_num_value(*right_visitor.result);
            result = std::make_unique<NumNode>(left_val - right_val);
        } else {
            result = std::make_unique<SubNode>(std::move(left_visitor.result), std::move(right_visitor.result));
        }
    }

    void visit(const MulNode& node) {
        FoldVisitor left_visitor;
        node.left->accept(left_visitor);
        FoldVisitor right_visitor;
        node.right->accept(right_visitor);

        // Try to fold constants
        if (is_num(*left_visitor.result) && is_num(*right_visitor.result)) {
            double left_val = get_num_value(*left_visitor.result);
            double right_val = get_num_value(*right_visitor.result);
            result = std::make_unique<NumNode>(left_val * right_val);
        } else {
            result = std::make_unique<MulNode>(std::move(left_visitor.result), std::move(right_visitor.result));
        }
    }

    void visit(const NegNode& node) {
        FoldVisitor operand_visitor;
        node.operand->accept(operand_visitor);

        // Try to fold constants
        if (is_num(*operand_visitor.result)) {
            double val = get_num_value(*operand_visitor.result);
            result = std::make_unique<NumNode>(-val);
        } else {
            result = std::make_unique<NegNode>(std::move(operand_visitor.result));
        }
    }

    void visit(const PowNode& node) {
        FoldVisitor base_visitor;
        node.base->accept(base_visitor);

        // Try to fold constants
        if (is_num(*base_visitor.result) && node.exponent == 0) {
            result = std::make_unique<NumNode>(1.0);
        } else if (is_num(*base_visitor.result) && node.exponent == 1) {
            double val = get_num_value(*base_visitor.result);
            result = std::make_unique<NumNode>(val);
        } else {
            result = std::make_unique<PowNode>(std::move(base_visitor.result), node.exponent);
        }
    }

    void visit(const ExpNode& node) {
        FoldVisitor operand_visitor;
        node.operand->accept(operand_visitor);
        result = std::make_unique<ExpNode>(std::move(operand_visitor.result));
    }

    void visit(const LogNode& node) {
        FoldVisitor operand_visitor;
        node.operand->accept(operand_visitor);
        result = std::make_unique<LogNode>(std::move(operand_visitor.result));
    }
};

class DiffVisitor {
public:
    std::string var_name;
    Ptr result;

    DiffVisitor(const std::string& var) : var_name(var) {}

    void visit(const NumNode& node) {
        result = std::make_unique<NumNode>(0.0);
    }

    void visit(const VarNode& node) {
        if (node.name == var_name) {
            result = std::make_unique<NumNode>(1.0);
        } else {
            result = std::make_unique<NumNode>(0.0);
        }
    }

    void visit(const AddNode& node) {
        DiffVisitor left_visitor(var_name);
        node.left->accept(left_visitor);
        DiffVisitor right_visitor(var_name);
        node.right->accept(right_visitor);
        result = std::make_unique<AddNode>(std::move(left_visitor.result), std::move(right_visitor.result));
    }

    void visit(const SubNode& node) {
        DiffVisitor left_visitor(var_name);
        node.left->accept(left_visitor);
        DiffVisitor right_visitor(var_name);
        node.right->accept(right_visitor);
        result = std::make_unique<SubNode>(std::move(left_visitor.result), std::move(right_visitor.result));
    }

    void visit(const MulNode& node) {
        // Product rule: (f * g)' = f' * g + f * g'
        DiffVisitor left_visitor(var_name);
        node.left->accept(left_visitor);
        DiffVisitor right_visitor(var_name);
        node.right->accept(right_visitor);

        Ptr left_term = std::make_unique<MulNode>(std::move(left_visitor.result), node.right->clone());
        Ptr right_term = std::make_unique<MulNode>(node.left->clone(), std::move(right_visitor.result));
        result = std::make_unique<AddNode>(std::move(left_term), std::move(right_term));
    }

    void visit(const NegNode& node) {
        DiffVisitor operand_visitor(var_name);
        node.operand->accept(operand_visitor);
        result = std::make_unique<NegNode>(std::move(operand_visitor.result));
    }

    void visit(const PowNode& node) {
        // Power rule: (f^n)' = n * f^(n-1) * f'
        if (node.exponent == 0) {
            result = std::make_unique<NumNode>(0.0);
        } else {
            DiffVisitor base_visitor(var_name);
            node.base->accept(base_visitor);
            Ptr base_term = std::make_unique<PowNode>(node.base->clone(), node.exponent - 1);
            Ptr diff_term = std::make_unique<MulNode>(std::make_unique<NumNode>(node.exponent), std::move(base_term));
            result = std::make_unique<MulNode>(std::move(diff_term), std::move(base_visitor.result));
        }
    }

    void visit(const ExpNode& node) {
        // Derivative of exp(f) is exp(f) * f'
        DiffVisitor operand_visitor(var_name);
        node.operand->accept(operand_visitor);
        Ptr exp_term = std::make_unique<ExpNode>(node.operand->clone());
        result = std::make_unique<MulNode>(std::move(exp_term), std::move(operand_visitor.result));
    }

    void visit(const LogNode& node) {
        // Derivative of log(f) is (1/f) * f'
        DiffVisitor operand_visitor(var_name);
        node.operand->accept(operand_visitor);
        Ptr inv_term = std::make_unique<MulNode>(std::make_unique<NumNode>(1.0), node.operand->clone());
        result = std::make_unique<MulNode>(std::move(inv_term), std::move(operand_visitor.result));
    }
};

