#include "include/ast.hpp"
#include <iostream>

int main() {
    using namespace ast;

    // Test basic operations
    auto expr = add(num(2.0), mul(num(3.0), num(4.0)));
    std::cout << "Expression: " << print(*expr) << std::endl;

    // Test clone
    auto cloned = clone(*expr);
    std::cout << "Cloned: " << print(*cloned) << std::endl;

    // Test fold
    auto folded = fold(*expr);
    std::cout << "Folded: " << print(*folded) << std::endl;

    // Test diff
    auto diffed = diff(*expr, "x");
    std::cout << "Diff: " << print(*diffed) << std::endl;

    return 0;
}

#include "include/ast.hpp"
#include <iostream>

int main() {
    using namespace ast;

    // Test complex expression: (x + 2) * (3 - y) + 5
    auto x = var("x");
    auto y = var("y");
    auto expr = add(mul(add(x, num(2.0)), sub(num(3.0), y)), num(5.0));

    std::cout << "Original: " << print(*expr) << std::endl;

    // Test fold with variables
    std::map<std::string, double> env = {{"x", 1.0}, {"y", 2.0}};
    double eval_result = eval(*expr, env);
    std::cout << "Evaluated: " << eval_result << std::endl;

    // Test clone
    auto cloned = clone(*expr);
    std::cout << "Cloned: " << print(*cloned) << std::endl;

    // Test fold (should simplify to constant)
    auto folded = fold(*expr);
    std::cout << "Folded: " << print(*folded) << std::endl;

    // Test diff with respect to x
    auto diffed = diff(*expr, "x");
    std::cout << "Diff wrt x: " << print(*diffed) << std::endl;

    // Test diff with respect to y
    auto diffed_y = diff(*expr, "y");
    std::cout << "Diff wrt y: " << print(*diffed_y) << std::endl;

    return 0;
}

