    auto expr1 = add(num(2.0), mul(num(3.0), num(4.0)));
    std::cout << "2 + 3 * 4: " << print(*expr1) << std::endl;

    // Test precedence: (2 + 3) * 4 (should have parentheses)
    auto expr2 = mul(add(num(2.0), num(3.0)), num(4.0));
