    // Test unary minus: -2 (should not have parentheses)
    auto expr3 = neg(num(2.0));
    std::cout << "-2: " << print(*expr3) << std::endl;

    // Test unary minus in expression: 2 + (-3) (should have parentheses)
    auto expr4 = add(num(2.0), neg(num(3.0)));
    std::cout << "2 + (-3): " << print(*expr4) << std::endl;

    // Test power: 2^3 (should not have parentheses)
    auto expr5 = pow_(num(2.0), 3.0);
    std::cout << "2^3: " << print(*expr5) << std::endl;

    // Test power with expression: (2 + 3)^2 (should have parentheses)
    auto expr6 = pow_(add(num(2.0), num(3.0)), 2.0);
    std::cout << "(2 + 3)^2: " << print(*expr6) << std::endl;

    return 0;
}

